# Component: GNNLayer
class GNNLayer(nn.Module):

    def __init__(self, hidden_dim, aggregation='sum', norm='batch', learn_norm=True, track_norm=False, gated=True):
        super(GNNLayer, self).__init__()
        self.hidden_dim = hidden_dim
        self.aggregation = aggregation
        self.norm = norm
        self.learn_norm = learn_norm
        self.track_norm = track_norm
        self.gated = gated
        assert self.gated, 'Use gating with GCN, pass the `--gated` flag'
        self.U = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.V = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.A = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.B = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.C = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.norm_h = {'layer': nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), 'batch': nn.BatchNorm1d(hidden_dim, affine=learn_norm, track_running_stats=track_norm)}.get(self.norm, None)
        self.norm_e = {'layer': nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), 'batch': nn.BatchNorm1d(hidden_dim, affine=learn_norm, track_running_stats=track_norm)}.get(self.norm, None)

    def forward(self, h, e, graph, mode='residual', edge_index=None, sparse=False):
        if not sparse:
            (batch_size, num_nodes, hidden_dim) = h.shape
        else:
            batch_size = None
            (num_nodes, hidden_dim) = h.shape
        h_in = h
        e_in = e
        Uh = self.U(h)
        if not sparse:
            Vh = self.V(h).unsqueeze(1).expand(-1, num_nodes, -1, -1)
        else:
            Vh = self.V(h[edge_index[1]])
        Ah = self.A(h)
        Bh = self.B(h)
        Ce = self.C(e)
        if not sparse:
            e = Ah.unsqueeze(1) + Bh.unsqueeze(2) + Ce
        else:
            e = Ah[edge_index[1]] + Bh[edge_index[0]] + Ce
        gates = torch.sigmoid(e)
        h = Uh + self.aggregate(Vh, graph, gates, edge_index=edge_index, sparse=sparse)
        if not sparse:
            h = self.norm_h(h.view(batch_size * num_nodes, hidden_dim)).view(batch_size, num_nodes, hidden_dim) if self.norm_h else h
        else:
            h = self.norm_h(h) if self.norm_h else h
        if not sparse:
            e = self.norm_e(e.view(batch_size * num_nodes * num_nodes, hidden_dim)).view(batch_size, num_nodes, num_nodes, hidden_dim) if self.norm_e else e
        else:
            e = self.norm_e(e) if self.norm_e else e
        h = F.relu(h)
        e = F.relu(e)
        if mode == 'residual':
            h = h_in + h
            e = e_in + e
        return (h, e)

    def aggregate(self, Vh, graph, gates, mode=None, edge_index=None, sparse=False):
        Vh = gates * Vh
        if not sparse:
            if (mode or self.aggregation) == 'mean':
                return torch.sum(Vh, dim=2) / torch.sum(graph, dim=2).unsqueeze(-1).type_as(Vh)
            elif (mode or self.aggregation) == 'max':
                return torch.max(Vh, dim=2)[0]
            else:
                return torch.sum(Vh, dim=2)
        else:
            sparseVh = SparseTensor(row=edge_index[0], col=edge_index[1], value=Vh, sparse_sizes=(graph.size(0), graph.size(1)))
            if (mode or self.aggregation) == 'mean':
                return sparse_mean(sparseVh, dim=1)
            elif (mode or self.aggregation) == 'max':
                return sparse_max(sparseVh, dim=1)
            else:
                return sparse_sum(sparseVh, dim=1)

# Component: PositionEmbeddingSine
class PositionEmbeddingSine(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        y_embed = x[:, :, 0]
        x_embed = x[:, :, 1]
        if self.normalize:
            y_embed = y_embed * self.scale
            x_embed = x_embed * self.scale
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2.0 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, :, None] / dim_t
        pos_y = y_embed[:, :, None] / dim_t
        pos_x = torch.stack((pos_x[:, :, 0::2].sin(), pos_x[:, :, 1::2].cos()), dim=3).flatten(2)
        pos_y = torch.stack((pos_y[:, :, 0::2].sin(), pos_y[:, :, 1::2].cos()), dim=3).flatten(2)
        pos = torch.cat((pos_y, pos_x), dim=2).contiguous()
        return pos

# Component: ScalarEmbeddingSine
class ScalarEmbeddingSine(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        x_embed = x
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, :, :, None] / dim_t
        pos_x = torch.stack((pos_x[:, :, :, 0::2].sin(), pos_x[:, :, :, 1::2].cos()), dim=4).flatten(3)
        return pos_x

# Component: ScalarEmbeddingSine1D
class ScalarEmbeddingSine1D(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        x_embed = x
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, None] / dim_t
        pos_x = torch.stack((pos_x[:, 0::2].sin(), pos_x[:, 1::2].cos()), dim=2).flatten(1)
        return pos_x

# Component: run_sparse_layer
def run_sparse_layer(layer, time_layer, out_layer, adj_matrix, edge_index, add_time_on_edge=True):

    def custom_forward(*inputs):
        x_in = inputs[0]
        e_in = inputs[1]
        time_emb = inputs[2]
        (x, e) = layer(x_in, e_in, adj_matrix, mode='direct', edge_index=edge_index, sparse=True)
        if add_time_on_edge:
            e = e + time_layer(time_emb)
        else:
            x = x + time_layer(time_emb)
        x = x_in + x
        e = e_in + out_layer(e)
        return (x, e)
    return custom_forward

# Component: normalize
def normalize(x):
    return nn.GroupNorm(32, x)

# Component: zero_module
def zero_module(module):
    for p in module.parameters():
        p.detach().zero_()
    return module

