# Component: AttentionModelEncoder
class AttentionModelEncoder(nn.Module):

    def __init__(self, env_name: str='tsp', embed_dim: int=128, init_embedding: nn.Module=None, num_heads: int=8, qkv_dim: int=16, num_layers: int=3, normalization: str='batch', feedforward_hidden: int=512, net: nn.Module=None, bias: bool=False, bias_k: bool=None, bias_v: bool=None, bias_combine: bool=True):
        super(AttentionModelEncoder, self).__init__()
        self.env_name = env_name
        self.initial_embedding = initial_embedding(self.env_name, {'embed_dim': embed_dim}) if init_embedding is None else init_embedding
        self.net = TransformerNet(num_layers, num_heads, qkv_dim, embed_dim, normalization, feedforward_hidden, bias=bias, bias_k=bias_k, bias_v=bias_v, bias_combine=bias_combine) if net is None else net

    def forward(self, td: TensorDict, mask: Optional[Tensor]=None, weights=None) -> Tuple[Tensor, Tensor]:
        if weights is None:
            init_out = self.initial_embedding(td)
            out = self.net(init_out)
        else:
            init_out = self.initial_embedding(td, weights=weights)
            out = self.net(init_out, weights=weights)
        return (out, init_out)

# Component: MultiHeadAttentionLayer
class MultiHeadAttentionLayer(nn.Module):

    def __init__(self, embed_dim: int, num_heads: int=8, qkv_dim: int=16, bias: bool=False, bias_k: bool=None, bias_v: bool=None, bias_combine: bool=True, multi_head_combine_used: bool=True):
        super().__init__()
        self.multi_head_combine_used = multi_head_combine_used
        if bias_k is None:
            bias_k = bias
        if bias_v is None:
            bias_v = bias
        self.Wq = nn.Linear(embed_dim, num_heads * qkv_dim, bias=bias)
        self.Wk = nn.Linear(embed_dim, num_heads * qkv_dim, bias=bias_k)
        self.Wv = nn.Linear(embed_dim, num_heads * qkv_dim, bias=bias_v)
        if multi_head_combine_used:
            self.multi_head_combine = nn.Linear(num_heads * qkv_dim, embed_dim, bias=bias_combine)
        self.num_heads = num_heads

    def forward(self, q_input, kv_input=None, mask=None, score_dim=None, sharp=False, weights=None):
        if kv_input is None:
            kv_input = q_input
        if weights is None:
            q = reshape_by_heads(self.Wq(q_input), head_num=self.num_heads)
            k = reshape_by_heads(self.Wk(kv_input), head_num=self.num_heads)
            v = reshape_by_heads(self.Wv(kv_input), head_num=self.num_heads)
            out = multi_head_attention(q, k, v, mask, score_dim=score_dim, sharp=sharp)
            if self.multi_head_combine_used:
                out = self.multi_head_combine(out)
        else:
            q = reshape_by_heads(F.linear(q_input, weights['Wq_weight'], bias=None), head_num=self.num_heads)
            k = reshape_by_heads(F.linear(kv_input, weights['Wk_weight'], bias=None), head_num=self.num_heads)
            v = reshape_by_heads(F.linear(kv_input, weights['Wv_weight'], bias=None), head_num=self.num_heads)
            out = multi_head_attention(q, k, v, mask, score_dim=score_dim, sharp=sharp)
            out = F.linear(out, weights['Wc_weight'], weights['Wc_bias'])
        return out

# Component: TransformerNet
class TransformerNet(nn.Module):

    def __init__(self, num_layers: int=6, num_heads: int=8, qkv_dim: int=16, embed_dim: int=128, normalization: str='batch', feedforward_hidden: int=512, bias: bool=False, bias_k: bool=None, bias_v: bool=None, bias_combine: bool=True):
        super().__init__()
        self.num_layers = num_layers
        self.MHA_layers = nn.ModuleList([SkipConnection(MultiHeadAttentionLayer(embed_dim, num_heads, qkv_dim, bias=bias, bias_k=bias_k, bias_v=bias_v, bias_combine=bias_combine)) for _ in range(num_layers)])
        self.norm1 = nn.ModuleList([Normalization(embed_dim, normalization) for _ in range(num_layers)])
        self.FF_layers = nn.ModuleList([SkipConnection(FeedForward(embed_dim, feedforward_hidden)) for _ in range(num_layers)])
        self.norm2 = nn.ModuleList([Normalization(embed_dim, normalization) for _ in range(num_layers)])

    def forward(self, input: torch.Tensor, weights=None) -> torch.Tensor:
        out = input
        for i in range(self.num_layers):
            if weights is None:
                out = self.MHA_layers[i](out)
                out = self.norm1[i](out)
                out = self.FF_layers[i](out)
                out = self.norm2[i](out)
            else:
                Norm_weights1 = {'weight': weights['encoder.net.norm1.{}.normalizer.weight'.format(i)], 'bias': weights['encoder.net.norm1.{}.normalizer.bias'.format(i)]}
                Norm_weights2 = {'weight': weights['encoder.net.norm2.{}.normalizer.weight'.format(i)], 'bias': weights['encoder.net.norm2.{}.normalizer.bias'.format(i)]}
                Mha_weights = {'Wq_weight': weights['encoder.net.MHA_layers.{}.0.Wq.weight'.format(i)], 'Wk_weight': weights['encoder.net.MHA_layers.{}.0.Wk.weight'.format(i)], 'Wv_weight': weights['encoder.net.MHA_layers.{}.0.Wv.weight'.format(i)], 'Wc_weight': weights['encoder.net.MHA_layers.{}.0.multi_head_combine.weight'.format(i)], 'Wc_bias': weights['encoder.net.MHA_layers.{}.0.multi_head_combine.bias'.format(i)]}
                FF_weights = {'weight1': weights['encoder.net.FF_layers.{}.0.W1.weight'.format(i)], 'bias1': weights['encoder.net.FF_layers.{}.0.W1.bias'.format(i)], 'weight2': weights['encoder.net.FF_layers.{}.0.W2.weight'.format(i)], 'bias2': weights['encoder.net.FF_layers.{}.0.W2.bias'.format(i)]}
                out = self.MHA_layers[i](out, weights=Mha_weights)
                out = self.norm1[i](out, weights=Norm_weights1)
                out = self.FF_layers[i](out, weights=FF_weights)
                out = self.norm2[i](out, weights=Norm_weights2)
        return out

# Component: Compatibility
class Compatibility(nn.Module):

    def __init__(self, embed_dim, n_heads, qkv_dim, key_dim, am_mode=True, **kwargs):
        super().__init__()
        self.embed_dim = embed_dim
        self.key_dim = key_dim
        self.am_mode = am_mode
        self.W_query = None
        self.W_key = None
        self.sub_glop = kwargs.get('sub_glop')
        if am_mode:
            self.W_query = nn.Linear(self.embed_dim, n_heads * qkv_dim, bias=False)
            self.W_key = nn.Linear(self.embed_dim, n_heads * qkv_dim, bias=False)

    def forward(self, q, encoded_nodes, mask=None, logit_clipping=10, penalty=None, **kwargs):
        if self.am_mode:
            sing_q = self.W_query(q)
            sing_head_k = self.W_key(encoded_nodes).transpose(-2, -1)
        else:
            sing_q = q
            if self.sub_glop:
                sing_head_k = kwargs.get('sing_head_k').transpose(1, 2)
            else:
                sing_head_k = encoded_nodes.transpose(-1, -2)
        score = torch.matmul(sing_q, sing_head_k)
        score_scaled = score / math.sqrt(self.key_dim)
        if penalty is not None:
            score_scaled += penalty
        score_clipped = logit_clipping * torch.tanh(score_scaled)
        if mask is not None:
            if q.dim() == 3:
                score_masked = score_clipped + mask
            elif q.dim() == 4:
                score_masked = score_clipped + mask[:, :, None, :].expand(-1, -1, sing_q.size(2), -1)
            else:
                raise RuntimeError(f'Invalid dimension of q: {q.dim()}. It should be either 3 or 4.')
        else:
            score_masked = score_clipped
        probs = F.softmax(score_masked, dim=-1)
        assert not torch.isnan(probs).any(), 'probs has nan, but it should not have any nans.'
        if q.dim() == 4:
            probs = probs.squeeze(dim=-2)
        return probs

# Component: TSPInitEmbedding
class TSPInitEmbedding(nn.Module):

    def __init__(self, embed_dim, linear_bias=True):
        super(TSPInitEmbedding, self).__init__()
        node_dim = 2
        self.init_embed = nn.Linear(node_dim, embed_dim, linear_bias)

    def forward(self, td, weights=None):
        if weights is None:
            out = self.init_embed(td['locs'])
        else:
            out = F.linear(td['locs'], weights['encoder.initial_embedding.init_embed.weight'], weights['encoder.initial_embedding.init_embed.bias'])
        return out

# Component: VRPInitEmbedding
class VRPInitEmbedding(nn.Module):

    def __init__(self, embed_dim, linear_bias=True, node_dim: int=3):
        super(VRPInitEmbedding, self).__init__()
        node_dim = node_dim
        self.init_embed_customers = nn.Linear(node_dim, embed_dim, linear_bias)
        self.init_embed_depot = nn.Linear(2, embed_dim, linear_bias)

    def forward(self, td, weights=None):
        (depot, customers) = (td['locs'][:, :1, :-1], td['locs'][:, 1:, :])
        if weights is None:
            depot_embedding = self.init_embed_depot(depot)
        else:
            depot_embedding = F.linear(depot, weights['encoder.initial_embedding.init_embed_depot.weight'], weights['encoder.initial_embedding.init_embed_depot.bias'])
        customers_demands = customers
        if weights is None:
            node_embeddings = self.init_embed_customers(customers_demands)
        else:
            node_embeddings = F.linear(customers_demands, weights['encoder.initial_embedding.init_embed_customers.weight'], weights['encoder.initial_embedding.init_embed_customers.bias'])
        out = torch.cat((depot_embedding, node_embeddings), dim=-2)
        return out

