        self.GatedMultiLoRALayer = []
        for module in self.encoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)
        for module in self.decoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)

    def get_basis_variant_binary_vector(self, td):
        (has_open, has_tw, has_limit, has_backhaul, backhaul_class) = MTVRPEnv.check_variants(td)
        prompt = torch.stack((has_open, has_tw, has_limit, has_backhaul), dim=-1).to(torch.float32)
        return prompt

    def set_basis_variant_binary_vector(self, td):
        basis_variant_binary_vector = self.get_basis_variant_binary_vector(td)
        for module in self.GatedMultiLoRALayer:
            module.basis_variant_binary_vector = basis_variant_binary_vector
        return

    def forward(self, td: TensorDict, env=None, phase: str='train', calc_reward: bool=True, return_actions: bool=True, return_entropy: bool=False, return_hidden: bool=False, return_init_embeds: bool=False, return_sum_log_likelihood: bool=True, actions=None, max_steps=1000000, **decoding_kwargs) -> dict:
        self.collect_GatedMultiLoRALayer()
        self.set_basis_variant_binary_vector(td)
        outdict = super(CadaMultiLoRAPolicy, self).forward(td=td, env=env, phase=phase, calc_reward=calc_reward, return_actions=return_actions, return_entropy=return_entropy, return_hidden=return_hidden, return_init_embeds=return_init_embeds, return_sum_log_likelihood=return_sum_log_likelihood, actions=actions, max_steps=max_steps, **decoding_kwargs)
        return outdict

