        LoRAPolicy.fix_basis_policy_weights(basis_policy)
        encoder = MultiLoRAEncoder(encoder=basis_policy.encoder, lora_rank=lora_rank, lora_alpha=lora_alpha, lora_act_func=lora_act_func, lora_n_experts=lora_n_experts, lora_top_k=lora_top_k, lora_temperature=lora_temperature, lora_use_trainable_layer=lora_use_trainable_layer, lora_use_dynamic_topK=lora_use_dynamic_topK, lora_use_basis_variants=lora_use_basis_variants, lora_use_linear=lora_use_linear, lora_use_basis_variants_as_input=lora_use_basis_variants_as_input)
        decoder = MultiLoRADecoder(decoder=basis_policy.decoder, lora_rank=lora_rank, lora_alpha=lora_alpha, lora_act_func=lora_act_func, lora_n_experts=lora_n_experts, lora_top_k=lora_top_k, lora_temperature=lora_temperature, lora_use_trainable_layer=lora_use_trainable_layer, lora_use_dynamic_topK=lora_use_dynamic_topK, lora_use_basis_variants=lora_use_basis_variants, lora_use_linear=lora_use_linear, lora_use_basis_variants_as_input=lora_use_basis_variants_as_input)
        super(MultiLoRAPolicy, self).__init__(encoder=encoder, decoder=decoder, embed_dim=embed_dim, num_heads=num_heads, normalization=normalization, feedforward_hidden=feedforward_hidden, env_name=env_name, use_graph_context=use_graph_context, context_embedding=context_embedding, **kwargs)
        self.lora_n_experts = lora_n_experts
        lora_fixed_params = self.lora_fixed_params()
        if lora_modules_ckpt_path != None:
            self.load_lora_modules(lora_fixed_params, lora_modules_ckpt_path)

    def collect_GatedMultiLoRALayer(self):
        self.GatedMultiLoRALayer = []
        for module in self.encoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)
        for module in self.decoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)

    def get_basis_variant_binary_vector(self, td):
        (has_open, has_tw, has_limit, has_backhaul, backhaul_class) = MTVRPEnv.check_variants(td)
        prompt = torch.stack((has_open, has_tw, has_limit, has_backhaul), dim=-1).to(torch.float32)
        return prompt

    def set_basis_variant_binary_vector(self, td):
        basis_variant_binary_vector = self.get_basis_variant_binary_vector(td)
        for module in self.GatedMultiLoRALayer:
            module.basis_variant_binary_vector = basis_variant_binary_vector
        return

    def forward(self, td: TensorDict, env=None, phase: str='train', calc_reward: bool=True, return_actions: bool=True, return_entropy: bool=False, return_hidden: bool=False, return_init_embeds: bool=False, return_sum_log_likelihood: bool=True, actions=None, max_steps=1000000, **decoding_kwargs) -> dict:
        self.collect_GatedMultiLoRALayer()
        self.set_basis_variant_binary_vector(td)
        outdict = super(MultiLoRAPolicy, self).forward(td=td, env=env, phase=phase, calc_reward=calc_reward, return_actions=return_actions, return_entropy=return_entropy, return_hidden=return_hidden, return_init_embeds=return_init_embeds, return_sum_log_likelihood=return_sum_log_likelihood, actions=actions, max_steps=max_steps, **decoding_kwargs)
        return outdict

