# Component: RouteFinderEncoder
class RouteFinderEncoder(nn.Module):

    def __init__(self, init_embedding: nn.Module=None, num_heads: int=8, embed_dim: int=128, num_layers: int=6, feedforward_hidden: int=512, normalization: str='instance', use_prenorm: bool=False, use_post_layers_norm: bool=False, parallel_gated_kwargs: dict=None, **transformer_kwargs):
        super(RouteFinderEncoder, self).__init__()
        if init_embedding is None:
            init_embedding = MTVRPInitEmbeddingRouteFinder(embed_dim=embed_dim)
        else:
            log.warning('Using custom init_embedding')
        self.init_embedding = init_embedding
        self.layers = nn.Sequential(*(TransformerBlock(embed_dim=embed_dim, num_heads=num_heads, normalization=normalization, use_prenorm=use_prenorm, feedforward_hidden=feedforward_hidden, parallel_gated_kwargs=parallel_gated_kwargs, **transformer_kwargs) for _ in range(num_layers)))
        self.post_layers_norm = Normalization(embed_dim, normalization) if use_post_layers_norm else None

    def forward(self, td: Tensor, mask: Union[Tensor, None]=None) -> Tuple[Tensor, Tensor]:
        init_h = self.init_embedding(td)
        h = init_h
        for layer in self.layers:
            h = layer(h, mask)
        if self.post_layers_norm is not None:
            h = self.post_layers_norm(h)
        return (h, init_h)

# Component: RMSNorm
class RMSNorm(nn.Module):

    def __init__(self, dim: int, eps: float=1e-05, **kwargs):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(dim))

    def _norm(self, x):
        return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)

    def forward(self, x):
        output = self._norm(x.float()).type_as(x)
        return output * self.weight

# Component: Normalization
class Normalization(nn.Module):

    def __init__(self, embed_dim, normalization='batch'):
        super(Normalization, self).__init__()
        if normalization != 'layer':
            normalizer_class = {'batch': nn.BatchNorm1d, 'instance': nn.InstanceNorm1d, 'rms': RMSNorm}.get(normalization, None)
            self.normalizer = normalizer_class(embed_dim, affine=True) if normalizer_class is not None else None
        else:
            self.normalizer = 'layer'
        if self.normalizer is None:
            log.error('Normalization type {} not found. Skipping normalization.'.format(normalization))

    def forward(self, x):
        if isinstance(self.normalizer, nn.BatchNorm1d):
            return self.normalizer(x.view(-1, x.size(-1))).view(*x.size())
        elif isinstance(self.normalizer, nn.InstanceNorm1d):
            return self.normalizer(x.permute(0, 2, 1)).permute(0, 2, 1)
        elif self.normalizer == 'layer':
            return (x - x.mean((1, 2)).view(-1, 1, 1)) / torch.sqrt(x.var((1, 2)).view(-1, 1, 1) + 1e-05)
        elif isinstance(self.normalizer, RMSNorm):
            return self.normalizer(x)
        else:
            assert self.normalizer is None, 'Unknown normalizer type {}'.format(self.normalizer)
            return x

# Component: ParallelGatedMLP
class ParallelGatedMLP(nn.Module):

    def __init__(self, hidden_size: int=128, inner_size_multiple_of: int=256, mlp_activation: str='silu', model_parallel_size: int=1):
        super().__init__()
        multiple_of = inner_size_multiple_of
        self.act_type = mlp_activation
        if self.act_type == 'gelu':
            self.act = F.gelu
        elif self.act_type == 'silu':
            self.act = F.silu
        else:
            raise NotImplementedError
        self.multiple_of = multiple_of * model_parallel_size
        inner_size = int(2 * hidden_size * 4 / 3)
        inner_size = self.multiple_of * ((inner_size + self.multiple_of - 1) // self.multiple_of)
        self.l1 = nn.Linear(in_features=hidden_size, out_features=inner_size, bias=False)
        self.l2 = nn.Linear(in_features=hidden_size, out_features=inner_size, bias=False)
        self.l3 = nn.Linear(in_features=inner_size, out_features=hidden_size, bias=False)

    def forward(self, z):
        (z1, z2) = (self.l1(z), self.l2(z))
        return self.l3(self.act(z1) * z2)

# Component: TransformerBlock
class TransformerBlock(nn.Module):

    def __init__(self, embed_dim: int=128, num_heads: int=8, feedforward_hidden: Optional[int]=None, normalization: Optional[str]='instance', use_prenorm: bool=False, bias: bool=True, sdpa_fn: Optional[Callable]=None, moe_kwargs: Optional[dict]=None, parallel_gated_kwargs: Optional[dict]=None):
        super(TransformerBlock, self).__init__()
        feedforward_hidden = 4 * embed_dim if feedforward_hidden is None else feedforward_hidden
        num_neurons = [feedforward_hidden] if feedforward_hidden > 0 else []
        if moe_kwargs is not None:
            ffn = MoE(embed_dim, embed_dim, num_neurons=num_neurons, **moe_kwargs)
        elif parallel_gated_kwargs is not None:
            ffn = ParallelGatedMLP(embed_dim, **parallel_gated_kwargs)
        else:
            ffn = MLP(input_dim=embed_dim, output_dim=embed_dim, num_neurons=num_neurons, hidden_act='ReLU')
        self.norm_attn = Normalization(embed_dim, normalization) if normalization is not None else lambda x: x
        self.attention = MultiHeadAttention(embed_dim, num_heads, bias=bias, sdpa_fn=sdpa_fn)
        self.norm_ffn = Normalization(embed_dim, normalization) if normalization is not None else lambda x: x
        self.ffn = ffn
        self.use_prenorm = use_prenorm

    def forward(self, x: Tensor, mask: Optional[Tensor]=None) -> Tensor:
        if self.use_prenorm:
            h = x + self.attention(self.norm_attn(x), mask)
            h = h + self.ffn(self.norm_ffn(h))
        else:
            h = self.norm_attn(x + self.attention(x, mask))
            h = self.norm_ffn(h + self.ffn(h))
        return h

