# Component: MTVRPInitEmbedding
class MTVRPInitEmbedding(nn.Module):

    def __init__(self, embed_dim=128, bias=False, num_global_feats=2, num_cust_feats=7, **kw):
        super(MTVRPInitEmbedding, self).__init__()
        global_feat_dim = num_global_feats
        self.project_global_feats = nn.Linear(global_feat_dim, embed_dim, bias=bias)
        customer_feat_dim = num_cust_feats
        self.project_customers_feats = nn.Linear(customer_feat_dim, embed_dim, bias=bias)
        self.embed_dim = embed_dim

    def forward(self, td):
        global_feats = td['locs'][:, :1, :]
        cust_feats = torch.cat((td['demand_linehaul'][..., 1:, None], td['demand_backhaul'][..., 1:, None], td['time_windows'][..., 1:, :], td['service_time'][..., 1:, None], td['locs'][:, 1:, :]), -1)
        global_feats = torch.nan_to_num(global_feats, nan=0.0, posinf=0.0, neginf=0.0)
        cust_feats = torch.nan_to_num(cust_feats, nan=0.0, posinf=0.0, neginf=0.0)
        global_embeddings = self.project_global_feats(global_feats)
        cust_embeddings = self.project_customers_feats(cust_feats)
        return torch.cat((global_embeddings, cust_embeddings), -2)

# Component: MTVRPInitEmbeddingRouteFinderBase
class MTVRPInitEmbeddingRouteFinderBase(nn.Module):

    def __init__(self, num_global_feats, num_cust_feats, embed_dim=128, bias=False, posinf_val=0.0):
        super(MTVRPInitEmbeddingRouteFinderBase, self).__init__()
        self.project_global_feats = nn.Linear(num_global_feats, embed_dim, bias=bias)
        self.project_customers_feats = nn.Linear(num_cust_feats, embed_dim, bias=bias)
        self.embed_dim = embed_dim
        self.posinf_val = posinf_val

    def _global_feats(self, td):
        raise NotImplementedError('This method should be overridden by subclasses')

    def _cust_feats(self, td):
        raise NotImplementedError('This method should be overridden by subclasses')

    def forward(self, td):
        global_feats = self._global_feats(td)
        cust_feats = self._cust_feats(td)
        global_feats = torch.nan_to_num(global_feats, posinf=self.posinf_val)
        cust_feats = torch.nan_to_num(cust_feats, posinf=self.posinf_val)
        global_embeddings = self.project_global_feats(global_feats)
        cust_embeddings = self.project_customers_feats(cust_feats)
        return torch.cat((global_embeddings, cust_embeddings), -2)

# Component: MTVRPInitEmbeddingRouteFinder
class MTVRPInitEmbeddingRouteFinder(MTVRPInitEmbeddingRouteFinderBase):

    def __init__(self, embed_dim=128, bias=False, posinf_val=0.0):
        super(MTVRPInitEmbeddingRouteFinder, self).__init__(num_global_feats=5, num_cust_feats=7, embed_dim=embed_dim, bias=bias, posinf_val=posinf_val)

    def _global_feats(self, td):
        return torch.cat([td['open_route'].float()[..., None], td['locs'][:, :1, :], td['distance_limit'][..., None], td['time_windows'][:, :1, 1:2]], -1)

    def _cust_feats(self, td):
        return torch.cat((td['locs'][..., 1:, :], td['demand_linehaul'][..., 1:, None], td['demand_backhaul'][..., 1:, None], td['time_windows'][..., 1:, :], td['service_time'][..., 1:, None]), -1)

# Component: MTVRPInitEmbeddingM
class MTVRPInitEmbeddingM(MTVRPInitEmbeddingRouteFinder):

    def __init__(self, embed_dim=128, bias=False, posinf_val=0.0):
        MTVRPInitEmbeddingRouteFinderBase.__init__(self, num_global_feats=5 + 1, num_cust_feats=7, embed_dim=embed_dim, bias=bias, posinf_val=posinf_val)

    def _global_feats(self, td):
        glob_feats = super(MTVRPInitEmbeddingM, self)._global_feats(td)
        is_mixed_backhaul = (td['backhaul_class'] == 2).float()
        return torch.cat([glob_feats, is_mixed_backhaul[..., None]], -1)

# Component: MTVRPInitEmbeddingFull
class MTVRPInitEmbeddingFull(MTVRPInitEmbeddingRouteFinder):

    def __init__(self, embed_dim=128, bias=False, posinf_val=0.0):
        super(MTVRPInitEmbeddingRouteFinder, self).__init__(num_global_feats=6, num_cust_feats=7, embed_dim=embed_dim, bias=bias, posinf_val=posinf_val)

    def _global_feats(self, td):
        num_depots = td['num_depots'].max().item()
        return torch.cat([td['open_route'].float()[..., None].repeat(1, num_depots, 1), td['locs'][:, :num_depots, :], td['distance_limit'][..., None].repeat(1, num_depots, 1), td['time_windows'][:, :num_depots, 1:2], (td['backhaul_class'] == 2).float()[..., None].repeat(1, num_depots, 1)], -1)

    def _cust_feats(self, td):
        num_depots = td['num_depots'].max().item()
        return torch.cat((td['locs'][..., num_depots:, :], td['demand_linehaul'][..., num_depots:, None], td['demand_backhaul'][..., num_depots:, None], td['time_windows'][..., num_depots:, :], td['service_time'][..., num_depots:, None]), -1)

# Component: EnvContext
class EnvContext(nn.Module):

    def __init__(self, embed_dim, step_context_dim=None, linear_bias=False):
        super(EnvContext, self).__init__()
        self.embed_dim = embed_dim
        step_context_dim = step_context_dim if step_context_dim is not None else embed_dim
        self.project_context = nn.Linear(step_context_dim, embed_dim, bias=linear_bias)

    def _cur_node_embedding(self, embeddings, td):
        cur_node_embedding = gather_by_index(embeddings, td['current_node'])
        return cur_node_embedding

    def _state_embedding(self, embeddings, td):
        raise NotImplementedError('Implement for each environment')

    def forward(self, embeddings, td):
        cur_node_embedding = self._cur_node_embedding(embeddings, td)
        state_embedding = self._state_embedding(embeddings, td)
        context_embedding = torch.cat([cur_node_embedding, state_embedding], -1)
        return self.project_context(context_embedding)

# Component: MTVRPContextEmbedding
class MTVRPContextEmbedding(EnvContext):

    def __init__(self, embed_dim=128, default_remain_dist=10):
        super(MTVRPContextEmbedding, self).__init__(embed_dim=embed_dim, step_context_dim=embed_dim + 4)
        self.default_remain_dist = default_remain_dist

    def _state_embedding(self, embeddings, td):
        mask = td['used_capacity_backhaul'] == 0
        used_capacity = torch.where(mask, td['used_capacity_linehaul'], td['used_capacity_backhaul'])
        available_load = td['vehicle_capacity'] - used_capacity
        remaining_dist = torch.nan_to_num(td['distance_limit'] - td['current_route_length'], posinf=self.default_remain_dist)
        context_feats = torch.cat((available_load, td['current_time'], td['open_route'].float(), remaining_dist), -1)
        return context_feats

