# Component: MTVRPContextEmbeddingM
class MTVRPContextEmbeddingM(MTVRPContextEmbeddingRouteFinder):

    def __init__(self, embed_dim=128, default_remain_dist=10):
        EnvContext.__init__(self, embed_dim=embed_dim, step_context_dim=embed_dim + 4)
        self.default_remain_dist = default_remain_dist

    def _state_embedding(self, embeddings, td):
        context_feats = super(MTVRPContextEmbeddingM, self)._state_embedding(embeddings, td)
        available_load_vrpmpd = (td['vehicle_capacity'] - td['used_capacity_backhaul']) * (td['backhaul_class'] == 2)
        return torch.cat((context_feats, available_load_vrpmpd), -1)

# Component: MTVRPContextEmbeddingFull
class MTVRPContextEmbeddingFull(MTVRPContextEmbeddingRouteFinder):

    def __init__(self, embed_dim=128, default_remain_dist=10):
        EnvContext.__init__(self, embed_dim=embed_dim, step_context_dim=embed_dim + 4 + 2)
        self.default_remain_dist = default_remain_dist

    def _state_embedding(self, embeddings, td):
        context_feats = super(MTVRPContextEmbeddingFull, self)._state_embedding(embeddings, td)
        available_load_vrpmpd = (td['vehicle_capacity'] - td['used_capacity_backhaul']) * (td['backhaul_class'] == 2)
        start_depot_location = gather_by_index(td['locs'], td['current_depot'], dim=-2)
        return torch.cat((context_feats, available_load_vrpmpd, start_depot_location), -1)

# Component: RouteFinderPolicy
class RouteFinderPolicy(AttentionModelPolicy):

    def __init__(self, embed_dim: int=128, num_encoder_layers: int=6, num_heads: int=8, normalization: str='instance', feedforward_hidden: int=512, parallel_gated_kwargs: dict=None, encoder_use_post_layers_norm: bool=False, encoder_use_prenorm: bool=False, env_name: str='mtvrp', use_graph_context: bool=False, init_embedding: MTVRPInitEmbeddingRouteFinder=None, context_embedding: MTVRPContextEmbeddingRouteFinder=None, extra_encoder_kwargs: dict={}, **kwargs):
        encoder = RouteFinderEncoder(init_embedding=init_embedding, num_heads=num_heads, embed_dim=embed_dim, num_layers=num_encoder_layers, feedforward_hidden=feedforward_hidden, normalization=normalization, use_prenorm=encoder_use_prenorm, use_post_layers_norm=encoder_use_post_layers_norm, parallel_gated_kwargs=parallel_gated_kwargs, **extra_encoder_kwargs)
        if context_embedding is None:
            context_embedding = MTVRPContextEmbeddingRouteFinder(embed_dim=embed_dim)
        dynamic_embedding = StaticEmbedding()
        super(RouteFinderPolicy, self).__init__(encoder=encoder, embed_dim=embed_dim, num_heads=num_heads, normalization=normalization, feedforward_hidden=feedforward_hidden, env_name=env_name, use_graph_context=use_graph_context, context_embedding=context_embedding, dynamic_embedding=dynamic_embedding, **kwargs)
